package com.cushty;

import com.cushty.loot.LootFilter;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CushtyConfig.GROUP)
public interface CushtyConfig extends Config
{
	String GROUP = "cushty";
	String THIRD_PARTY_WARNING = "This plugin submits your IP address to a 3rd party website not controlled or verified by the RuneLite Developers.";

	@ConfigSection(
		name = "Connection",
		description = "Where to send events. There is no default server. Paste a server URL and a bearer token. Nothing is uploaded until you enable a feature below.",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigSection(
		name = "Screenshots",
		description = "Manual screenshots",
		position = 1
	)
	String screenshotSection = "screenshots";

	@ConfigSection(
		name = "Valuable drops",
		description = "Automatically share valuable drops",
		position = 2
	)
	String lootSection = "loot";

	@ConfigSection(
		name = "Pets",
		description = "Automatically share pet drops",
		position = 3
	)
	String petSection = "pets";

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "HTTPS server that receives your events. There is no default. Leave blank to send nothing. Test connection also contacts this server.",
		section = connectionSection,
		position = 0
	)
	default String serverUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "token",
		name = "Token",
		description = "Bearer token for the server above. Treat it like a password.",
		secret = true,
		section = connectionSection,
		position = 1
	)
	default String token()
	{
		return "";
	}

	@ConfigItem(
		keyName = "includeRsn",
		name = "Include RSN",
		description = "Show your in-game name on posts. When off, your Discord name is used.",
		section = connectionSection,
		position = 2
	)
	default boolean includeRsn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatNotifications",
		name = "Chat notifications",
		description = "Print a game chat message when something is sent or fails",
		section = connectionSection,
		position = 3
	)
	default boolean chatNotifications()
	{
		return true;
	}

	@ConfigItem(
		keyName = "manualEnabled",
		name = "Enable manual screenshots",
		description = "Send a screenshot of the game with the hotkey or the sidebar panel",
		warning = THIRD_PARTY_WARNING,
		section = screenshotSection,
		position = 0
	)
	default boolean manualEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "screenshotHotkey",
		name = "Screenshot hotkey",
		description = "Hotkey that sends a screenshot immediately",
		section = screenshotSection,
		position = 1
	)
	default Keybind screenshotHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "lootEnabled",
		name = "Enable valuable drops",
		description = "Send a screenshot when you receive a valuable drop",
		warning = THIRD_PARTY_WARNING,
		section = lootSection,
		position = 0
	)
	default boolean lootEnabled()
	{
		return false;
	}

	@Range(min = LootFilter.MIN_STACK_VALUE)
	@Units(" gp")
	@ConfigItem(
		keyName = "lootMinValue",
		name = "Minimum value",
		description = "Send when a single item stack in a drop is worth at least this much (Grand Exchange price). Cannot be set below 5M.",
		section = lootSection,
		position = 1
	)
	default int lootMinValue()
	{
		return LootFilter.MIN_STACK_VALUE;
	}

	@ConfigItem(
		keyName = "petsEnabled",
		name = "Enable pets",
		description = "Send a screenshot when you get a pet (including duplicates)",
		warning = THIRD_PARTY_WARNING,
		section = petSection,
		position = 0
	)
	default boolean petsEnabled()
	{
		return false;
	}
}

package com.cushty;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** Sidebar panel: send a screenshot with an optional caption, and test the connection. */
class CushtyPanel extends PluginPanel
{
	private static final int MAX_CAPTION = 500;

	private final JTextArea caption = new JTextArea(4, 20);
	private final JButton sendButton = new JButton("Send screenshot");
	private final JButton testButton = new JButton("Test connection");
	private final JLabel status = new JLabel();

	CushtyPanel(Consumer<String> onSend, Runnable onTest)
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Cushty");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		JLabel captionLabel = new JLabel("Caption (optional)");
		captionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		caption.setLineWrap(true);
		caption.setWrapStyleWord(true);
		caption.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		caption.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		JScrollPane captionScroll = new JScrollPane(caption);
		captionScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));

		JPanel top = new JPanel(new BorderLayout(0, 6));
		top.add(title, BorderLayout.NORTH);
		top.add(captionLabel, BorderLayout.CENTER);
		top.add(captionScroll, BorderLayout.SOUTH);

		sendButton.addActionListener(e ->
		{
			String text = caption.getText().trim();
			onSend.accept(text.length() > MAX_CAPTION ? text.substring(0, MAX_CAPTION) : text);
		});
		testButton.addActionListener(e -> onTest.run());

		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 6));
		buttons.add(sendButton);
		buttons.add(testButton);

		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setFont(FontManager.getRunescapeSmallFont());

		JPanel bottom = new JPanel(new BorderLayout(0, 8));
		bottom.add(buttons, BorderLayout.NORTH);
		bottom.add(status, BorderLayout.CENTER);

		add(top, BorderLayout.NORTH);
		add(bottom, BorderLayout.CENTER);
	}

	/** Safe to call from any thread. */
	void setStatus(String message, boolean error)
	{
		SwingUtilities.invokeLater(() ->
		{
			status.setText("<html>" + escape(message) + "</html>");
			status.setForeground(error ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
		});
	}

	/** Safe to call from any thread. */
	void setBusy(boolean busy)
	{
		SwingUtilities.invokeLater(() -> sendButton.setEnabled(!busy));
	}

	/** Safe to call from any thread. */
	void clearCaption()
	{
		SwingUtilities.invokeLater(() -> caption.setText(""));
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.cushty;

import com.cushty.api.CushtyApiClient;
import com.cushty.api.EventPayload;
import com.cushty.capture.ScreenshotCapture;
import com.cushty.loot.LootFilter;
import com.cushty.pets.PetMessages;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;
import okhttp3.HttpUrl;

@Slf4j
@PluginDescriptor(
	name = "Cushty",
	description = "Share your drops, pets, and game-view screenshots with a clan Discord you configure",
	tags = {"discord", "screenshot", "clan", "drops", "loot", "pet"}
)
public class CushtyPlugin extends Plugin
{
	/** Keep in line with the bot's MAX_UPLOAD_MB default. */
	private static final int MAX_UPLOAD_BYTES = 8 * 1024 * 1024;
	/** Wait a couple of ticks so the pet and the clan broadcast are visible in the shot. */
	private static final int PET_CAPTURE_DELAY_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CushtyConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScreenshotCapture screenshotCapture;

	@Inject
	private CushtyApiClient api;

	private CushtyPanel panel;
	private NavigationButton navButton;
	private EventPayload pendingPet;
	private int pendingPetTicks;

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.screenshotHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			sendManual(null, false);
		}
	};

	@Provides
	CushtyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CushtyConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new CushtyPanel(caption -> sendManual(caption, true), this::testConnection);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Cushty")
			.icon(icon)
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		keyManager.registerKeyListener(hotkeyListener);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		pendingPet = null;
	}

	// ---- Manual screenshots -------------------------------------------------------------------

	private void sendManual(String caption, boolean fromPanel)
	{
		if (!config.manualEnabled())
		{
			report("Turn on 'Enable manual screenshots' in the Cushty settings first.", true);
			return;
		}
		EventPayload payload = EventPayload.builder()
			.type(EventPayload.TYPE_MANUAL)
			.caption(caption == null || caption.isBlank() ? null : caption)
			.build();
		send(payload, fromPanel);
	}

	private void testConnection()
	{
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			report("Set an HTTPS server URL and token first.", true);
			return;
		}
		api.checkConnection(server, token, listener(false));
	}

	// ---- Valuable drops -----------------------------------------------------------------------

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		handleLoot(event.getNpc().getName(), event.getItems());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		handleLoot(event.getPlayer().getName(), event.getItems());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// NPC and player kills arrive via the events above; this covers chests, raids, pickpockets etc.
		if (event.getType() == LootRecordType.EVENT || event.getType() == LootRecordType.PICKPOCKET)
		{
			handleLoot(event.getName(), event.getItems());
		}
	}

	private void handleLoot(String source, Collection<ItemStack> items)
	{
		if (!config.lootEnabled() || items.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack stack : items)
		{
			quantities.merge(itemManager.canonicalize(stack.getId()), stack.getQuantity(), Integer::sum);
		}

		List<EventPayload.LootItem> drop = new ArrayList<>(quantities.size());
		quantities.forEach((id, quantity) -> drop.add(new EventPayload.LootItem(
			id,
			itemManager.getItemComposition(id).getName(),
			quantity,
			itemManager.getItemPrice(id))));

		LootFilter filter = new LootFilter(config.lootMinValue());
		LootFilter.Result result = filter.select(drop);
		if (result.isEmpty())
		{
			return;
		}

		String name = source == null || source.isBlank() ? "Unknown" : Text.removeTags(source);
		send(EventPayload.builder()
			.type(EventPayload.TYPE_LOOT)
			.loot(new EventPayload.Loot(name, result.getItems(), result.getTotalValue()))
			.build(), false);
	}

	// ---- Pets ---------------------------------------------------------------------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.petsEnabled() || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		PetMessages.Result result = PetMessages.classify(message);
		if (result == PetMessages.Result.NONE)
		{
			return;
		}
		pendingPet = EventPayload.builder()
			.type(EventPayload.TYPE_PET)
			.pet(new EventPayload.Pet(result == PetMessages.Result.DUPLICATE, message))
			.build();
		pendingPetTicks = PET_CAPTURE_DELAY_TICKS;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (pendingPet != null && --pendingPetTicks <= 0)
		{
			EventPayload pet = pendingPet;
			pendingPet = null;
			send(pet, false);
		}
	}

	// ---- Sending ------------------------------------------------------------------------------

	/**
	 * Captures the next frame and posts it. Safe to call from any thread.
	 *
	 * @param fromPanel whether the sidebar panel should show progress and clear its caption
	 */
	private void send(EventPayload payload, boolean fromPanel)
	{
		HttpUrl server = CushtyApiClient.parseServerUrl(config.serverUrl());
		String token = config.token().trim();
		if (server == null || token.isEmpty())
		{
			report("Set an HTTPS server URL and token in the Cushty settings.", true);
			return;
		}

		CushtyPanel currentPanel = panel;
		if (fromPanel && currentPanel != null)
		{
			currentPanel.setBusy(true);
		}

		clientThread.invokeLater(() ->
		{
			Player player = client.getLocalPlayer();
			if (config.includeRsn() && player != null && player.getName() != null)
			{
				payload.setRsn(Text.sanitize(player.getName()));
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				payload.setWorld(client.getWorld());
			}

			CushtyApiClient.ResultListener listener = listener(fromPanel);
			screenshotCapture.captureNextFrame()
				.orTimeout(10, TimeUnit.SECONDS)
				.whenComplete((png, error) ->
				{
					if (error != null)
					{
						log.debug("Screenshot capture failed", error);
						listener.onFailure("Could not capture a screenshot");
					}
					else if (png.length > MAX_UPLOAD_BYTES)
					{
						listener.onFailure("Screenshot is too large to upload");
					}
					else
					{
						api.sendEvent(server, token, payload, png, listener);
					}
				});
		});
	}

	private CushtyApiClient.ResultListener listener(boolean fromPanel)
	{
		return new CushtyApiClient.ResultListener()
		{
			@Override
			public void onSuccess(String message)
			{
				finish(message, false);
			}

			@Override
			public void onFailure(String message)
			{
				finish(message, true);
			}

			private void finish(String message, boolean error)
			{
				CushtyPanel current = panel;
				if (fromPanel && current != null)
				{
					current.setBusy(false);
					if (!error)
					{
						current.clearCaption();
					}
				}
				report(message, error);
			}
		};
	}

	/** Shows a status message in the panel and, if enabled, in game chat. Safe from any thread. */
	private void report(String message, boolean error)
	{
		CushtyPanel current = panel;
		if (current != null)
		{
			current.setStatus(message, error);
		}
		if (!config.chatNotifications())
		{
			return;
		}
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Cushty] ")
			.append(ChatColorType.NORMAL)
			.append(message)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}
}

package com.cushty.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the configured server. All calls are asynchronous on the OkHttp thread pool; callbacks are
 * invoked on that pool too, never on the client thread.
 */
@Slf4j
@Singleton
public class CushtyApiClient
{
	private static final MediaType PNG = MediaType.parse("image/png");

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	CushtyApiClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	public interface ResultListener
	{
		void onSuccess(String message);

		void onFailure(String message);
	}

	/**
	 * Validates the configured server URL. HTTPS is required so tokens and screenshots are never
	 * sent in the clear; plain HTTP is only allowed for a bot running on this machine.
	 *
	 * @return the parsed URL, or null if it is unusable
	 */
	public static HttpUrl parseServerUrl(String value)
	{
		if (value == null || value.isBlank())
		{
			return null;
		}
		HttpUrl url = HttpUrl.parse(value.trim());
		if (url == null)
		{
			return null;
		}
		boolean local = url.host().equals("localhost") || url.host().equals("127.0.0.1");
		return url.isHttps() || local ? url : null;
	}

	public void sendEvent(HttpUrl server, String token, EventPayload payload, byte[] png, ResultListener listener)
	{
		RequestBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload", gson.toJson(payload))
			.addFormDataPart("screenshot", "screenshot.png", RequestBody.create(PNG, png))
			.build();

		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments("v1/events").build())
			.header("Authorization", "Bearer " + token)
			.post(body)
			.build();

		execute(request, listener, json -> listener.onSuccess("Posted to Discord"));
	}

	public void checkConnection(HttpUrl server, String token, ResultListener listener)
	{
		Request request = new Request.Builder()
			.url(server.newBuilder().addPathSegments("v1/me").build())
			.header("Authorization", "Bearer " + token)
			.get()
			.build();

		execute(request, listener, json ->
		{
			String name = json != null && json.has("displayName") ? json.get("displayName").getAsString() : "unknown";
			listener.onSuccess("Connected as " + name);
		});
	}

	private void execute(Request request, ResultListener listener, Consumer<JsonObject> onOk)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Cushty request failed", e);
				listener.onFailure("Could not reach the Cushty server");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					JsonObject json = parse(responseBody);
					if (response.isSuccessful())
					{
						onOk.accept(json);
						return;
					}
					String message = json != null && json.has("message")
						? json.get("message").getAsString()
						: "Server returned HTTP " + response.code();
					listener.onFailure(message);
				}
			}
		});
	}

	private JsonObject parse(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(body.charStream(), JsonObject.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}
}

package com.cushty.api;

import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * JSON body of {@code POST /v1/events}. Fields are {@code type}, optional {@code rsn},
 * {@code caption} and {@code world}, plus {@code loot} or {@code pet}. Nulls are omitted.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class EventPayload
{
	public static final String TYPE_MANUAL = "manual";
	public static final String TYPE_LOOT = "loot";
	public static final String TYPE_PET = "pet";

	private String type;
	private String rsn;
	private String caption;
	private Integer world;
	private Loot loot;
	private Pet pet;

	@Data
	@AllArgsConstructor
	public static class Loot
	{
		private String source;
		private List<LootItem> items;
		private long totalValue;
	}

	@Data
	@AllArgsConstructor
	public static class LootItem
	{
		private int id;
		private String name;
		private int quantity;
		private long priceEach;

		public long stackValue()
		{
			return priceEach * quantity;
		}
	}

	@Data
	@AllArgsConstructor
	public static class Pet
	{
		private boolean duplicate;
		private String message;
	}
}

package com.cushty.capture;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.DrawManager;

/**
 * Captures the next rendered game frame. This is the game canvas only: never the desktop, other
 * windows or the RuneLite sidebar.
 */
@Singleton
public class ScreenshotCapture
{
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	ScreenshotCapture(DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.drawManager = drawManager;
		this.executor = executor;
	}

	/** @return a future completed with PNG bytes, off the client thread */
	public CompletableFuture<byte[]> captureNextFrame()
	{
		CompletableFuture<byte[]> result = new CompletableFuture<>();
		drawManager.requestNextFrameListener(frame ->
		{
			// The frame buffer may be reused by the renderer, so copy it before leaving this callback.
			BufferedImage copy = copy(frame);
			executor.execute(() ->
			{
				try
				{
					result.complete(encodePng(copy));
				}
				catch (IOException e)
				{
					result.completeExceptionally(e);
				}
			});
		});
		return result;
	}

	private static BufferedImage copy(Image frame)
	{
		BufferedImage image = new BufferedImage(frame.getWidth(null), frame.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(frame, 0, 0, null);
		graphics.dispose();
		return image;
	}

	static byte[] encodePng(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		if (!ImageIO.write(image, "png", out))
		{
			throw new IOException("No PNG encoder available");
		}
		return out.toByteArray();
	}
}

package com.cushty.loot;

import com.cushty.api.EventPayload;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import lombok.Value;

/** Decides which items in a drop are worth sharing. Free of RuneLite types so it can be unit tested. */
public final class LootFilter
{
	public static final int MAX_ITEMS = 25;
	/** Hard floor so the threshold cannot be edited down to pocket change. */
	public static final int MIN_STACK_VALUE = 5_000_000;

	private final long minStackValue;

	public LootFilter(long minStackValue)
	{
		this.minStackValue = Math.max(minStackValue, MIN_STACK_VALUE);
	}

	@Value
	public static class Result
	{
		List<EventPayload.LootItem> items;
		long totalValue;

		public boolean isEmpty()
		{
			return items.isEmpty();
		}
	}

	/**
	 * Returns the items to share, most valuable first. The total value covers the whole drop,
	 * not just the selected items.
	 */
	public Result select(Collection<EventPayload.LootItem> drop)
	{
		long total = 0;
		List<EventPayload.LootItem> selected = new ArrayList<>();
		for (EventPayload.LootItem item : drop)
		{
			total += item.stackValue();
			if (item.stackValue() >= minStackValue)
			{
				selected.add(item);
			}
		}

		selected.sort(Comparator.comparingLong(EventPayload.LootItem::stackValue).reversed());
		if (selected.size() > MAX_ITEMS)
		{
			selected = new ArrayList<>(selected.subList(0, MAX_ITEMS));
		}
		return new Result(selected, total);
	}
}

package com.cushty.pets;

/** Recognises the game messages shown when a pet is rolled. */
public final class PetMessages
{
	public enum Result
	{
		NONE,
		NEW_PET,
		DUPLICATE
	}

	private static final String FOLLOWED = "You have a funny feeling like you're being followed";
	private static final String BACKPACK = "You feel something weird sneaking into your backpack";
	private static final String DUPLICATE = "You have a funny feeling like you would have been followed";

	private PetMessages()
	{
	}

	/** @param message the chat message with formatting tags already removed */
	public static Result classify(String message)
	{
		if (message == null)
		{
			return Result.NONE;
		}
		if (message.startsWith(DUPLICATE))
		{
			return Result.DUPLICATE;
		}
		if (message.startsWith(FOLLOWED) || message.startsWith(BACKPACK))
		{
			return Result.NEW_PET;
		}
		return Result.NONE;
	}
}

